(async () => {
  const root = document.querySelector('[data-window-gallery]');
  root.scrollIntoView();
  await new Promise(r => setTimeout(r, 6000));
  const stage = root.querySelector('[data-wg-stage]');
  const canvas = stage.querySelector('canvas');
  const r = stage.getBoundingClientRect();
  return {cls: root.className, stage: [Math.round(r.x), Math.round(r.y + window.scrollY), Math.round(r.width), Math.round(r.height)],
          canvas: canvas ? [canvas.width, canvas.height] : null,
          swatchCols: getComputedStyle(root.querySelector('.wg__swatches')).gridTemplateColumns};
})()
